import{c as a,Q as s,j as e,m as l}from"./chunks/framework.DOi4mjdC.js";const n="data:image/png;base64,",m=JSON.parse('{"title":"Axpy","description":"","frontmatter":{},"headers":[{"level":1,"title":"Axpy","slug":"axpy"},{"level":2,"title":"产品支持情况","slug":"产品支持情况"},{"level":2,"title":"功能说明","slug":"功能说明"},{"level":2,"title":"函数原型","slug":"函数原型"},{"level":2,"title":"参数说明","slug":"参数说明"},{"level":2,"title":"返回值说明","slug":"返回值说明"},{"level":2,"title":"约束说明","slug":"约束说明"},{"level":2,"title":"调用示例","slug":"调用示例"}],"relativePath":"api/SIMD-API/基础API/Memory矢量计算/复合计算/Axpy.md","filePath":"api/SIMD-API/基础API/Memory矢量计算/复合计算/Axpy.md"}'),d={name:"api/SIMD-API/基础API/Memory矢量计算/复合计算/Axpy.md"};function p(i,t,o,r,c,A){return s(),e("div",null,[...t[0]||(t[0]=[l('<h1 id="axpy" tabindex="-1">Axpy <a class="header-anchor" href="#axpy" aria-label="Permalink to &quot;Axpy&quot;">​</a></h1><h2 id="产品支持情况" tabindex="-1">产品支持情况 <a class="header-anchor" href="#产品支持情况" aria-label="Permalink to &quot;产品支持情况&quot;">​</a></h2><table tabindex="0"><thead><tr><th>产品</th><th>是否支持</th></tr></thead><tbody><tr><td>Ascend 950PR/Ascend 950DT</td><td>√</td></tr><tr><td>Atlas A3 训练系列产品/Atlas A3 推理系列产品</td><td>√</td></tr><tr><td>Atlas A2 训练系列产品/Atlas A2 推理系列产品</td><td>√</td></tr><tr><td>Atlas 200I/500 A2 推理产品</td><td>√</td></tr><tr><td>Atlas 推理系列产品AI Core</td><td>√</td></tr><tr><td>Atlas 推理系列产品Vector Core</td><td>x</td></tr><tr><td>Atlas 训练系列产品</td><td>√</td></tr><tr><td>Kirin X90</td><td>√</td></tr><tr><td>Kirin 9030</td><td>√</td></tr></tbody></table><h2 id="功能说明" tabindex="-1">功能说明 <a class="header-anchor" href="#功能说明" aria-label="Permalink to &quot;功能说明&quot;">​</a></h2><p>源操作数src中每个元素与标量求积后和目的操作数dst中的对应元素相加，计算公式如下：</p><p><img src="'+n+`" alt=""></p><h2 id="函数原型" tabindex="-1">函数原型 <a class="header-anchor" href="#函数原型" aria-label="Permalink to &quot;函数原型&quot;">​</a></h2><ul><li><p>tensor前n个数据计算</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>template &lt;typename T, typename U&gt;</span></span>
<span class="line"><span>__aicore__ inline void Axpy(const LocalTensor&lt;T&gt;&amp; dst, const LocalTensor&lt;U&gt;&amp; src, const U&amp; scalarValue, const int32_t&amp; count)</span></span></code></pre></div></li><li><p>tensor高维切分计算</p><ul><li><p>mask逐bit模式</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>template &lt;typename T, typename U, bool isSetMask = true&gt;</span></span>
<span class="line"><span>__aicore__ inline void Axpy(const LocalTensor&lt;T&gt;&amp; dst, const LocalTensor&lt;U&gt;&amp; src, const U&amp; scalarValue, uint64_t mask[], const uint8_t repeatTime, const UnaryRepeatParams&amp; repeatParams)</span></span></code></pre></div></li><li><p>mask连续模式</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>template &lt;typename T, typename U, bool isSetMask = true&gt;</span></span>
<span class="line"><span>__aicore__ inline void Axpy(const LocalTensor&lt;T&gt;&amp; dst, const LocalTensor&lt;U&gt;&amp; src, const U&amp; scalarValue, uint64_t mask, const uint8_t repeatTime, const UnaryRepeatParams&amp; repeatParams)</span></span></code></pre></div></li></ul></li></ul><h2 id="参数说明" tabindex="-1">参数说明 <a class="header-anchor" href="#参数说明" aria-label="Permalink to &quot;参数说明&quot;">​</a></h2><p><strong>表 1</strong> 模板参数说明</p><table tabindex="0"><thead><tr><th>参数名</th><th>描述</th></tr></thead><tbody><tr><td>T</td><td>目的操作数数据类型。目的操作数和源操作数的数据类型约束请参考表3。 Atlas 训练系列产品，支持的数据类型为：half/float Atlas 推理系列产品AI Core，支持的数据类型为：half/float Atlas A2 训练系列产品/Atlas A2 推理系列产品，支持的数据类型为：half/float Atlas A3 训练系列产品/Atlas A3 推理系列产品，支持的数据类型为：half/float Atlas 200I/500 A2 推理产品，支持的数据类型为：half/float Ascend 950PR/Ascend 950DT，支持的数据类型为：half/float/bfloat16_t/uint64_t/int64_t Kirin X90，支持的数据类型为：half、float。 Kirin 9030，支持的数据类型为：half、float。</td></tr><tr><td>U</td><td>源操作数数据类型。 Atlas 训练系列产品，支持的数据类型为：half/float Atlas 推理系列产品AI Core，支持的数据类型为：half/float Atlas A2 训练系列产品/Atlas A2 推理系列产品，支持的数据类型为：half/float Atlas A3 训练系列产品/Atlas A3 推理系列产品，支持的数据类型为：half/float Atlas 200I/500 A2 推理产品，支持的数据类型为：half/float Ascend 950PR/Ascend 950DT，支持的数据类型为：half/float/bfloat16_t/uint64_t/int64_t Kirin X90，支持的数据类型为：half、float。 Kirin 9030，支持的数据类型为：half、float。</td></tr><tr><td>isSetMask</td><td>是否在接口内部设置mask。 true，表示在接口内部设置mask。false，表示在接口外部设置mask，开发者需要使用SetVectorMask接口设置mask值。这种模式下，接口入参中的mask值设置为占位符MASK_PLACEHOLDER，用于占位，无实际含义。</td></tr></tbody></table><p><strong>表 2</strong> 参数说明</p><table tabindex="0"><thead><tr><th>参数名称</th><th>输入/输出</th><th>说明</th></tr></thead><tbody><tr><td>dst</td><td>输出</td><td>目的操作数。 类型为LocalTensor，支持的TPosition为VECIN/VECCALC/VECOUT。 LocalTensor的起始地址需要32字节对齐。</td></tr><tr><td>src</td><td>输入</td><td>源操作数。 类型为LocalTensor，支持的TPosition为VECIN/VECCALC/VECOUT。 LocalTensor的起始地址需要32字节对齐。</td></tr><tr><td>scalarValue</td><td>输入</td><td>源操作数，scalar标量。scalarValue的数据类型需要和src保持一致。</td></tr><tr><td>count</td><td>输入</td><td>参与计算的元素个数。</td></tr><tr><td>mask/mask[]</td><td>输入</td><td>mask用于控制每次迭代内参与计算的元素。 逐bit模式：可以按位控制哪些元素参与计算，bit位的值为1表示参与计算，0表示不参与。 mask为数组形式，数组长度和数组元素的取值范围和操作数的数据类型有关。当操作数为16位时，数组长度为2，mask[0]、mask[1]∈[0, 264-1]并且不同时为0；当操作数为32位时，数组长度为1，mask[0]∈(0, 264-1]；当操作数为64位时，数组长度为1，mask[0]∈(0, 232-1]。 例如，mask=[8, 0]，8=0b1000，表示仅第4个元素参与计算。 连续模式：表示前面连续的多少个元素参与计算。取值范围和操作数的数据类型有关，数据类型不同，每次迭代内能够处理的元素个数最大值不同。当操作数为16位时，mask∈[1, 128]；当操作数为32位时，mask∈[1, 64]；当操作数为64位时，mask∈[1, 32]。</td></tr><tr><td>repeatTime</td><td>输入</td><td>重复迭代次数。 矢量计算单元，每次读取连续的256Bytes数据进行计算，为完成对输入数据的处理，必须通过多次迭代（repeat）才能完成所有数据的读取与计算。repeatTime表示迭代的次数。 关于该参数的具体描述请参考高维切分API。</td></tr><tr><td>repeatParams</td><td>输入</td><td>控制操作数地址步长的参数。UnaryRepeatParams类型，包含操作数相邻迭代间相同DataBlock的地址步长，操作数同一迭代内不同DataBlock的地址步长等参数。 相邻迭代间的地址步长参数说明请参考repeatStride；同一迭代内DataBlock的地址步长参数说明请参考dataBlockStride。</td></tr></tbody></table><p><strong>表 3</strong> 数据类型约束</p><table tabindex="0"><thead><tr><th>src数据类型</th><th>scalar数据类型</th><th>dst数据类型</th><th>PAR</th><th>支持的型号</th></tr></thead><tbody><tr><td>half</td><td>half</td><td>half</td><td>128</td><td>Atlas 训练系列产品 Atlas A2 训练系列产品/Atlas A2 推理系列产品 Atlas A3 训练系列产品/Atlas A3 推理系列产品 Atlas 推理系列产品AI Core Atlas 200I/500 A2 推理产品 Ascend 950PR/Ascend 950DT Kirin X90 Kirin 9030</td></tr><tr><td>float</td><td>float</td><td>float</td><td>64</td><td>Atlas 训练系列产品 Atlas A2 训练系列产品/Atlas A2 推理系列产品 Atlas A3 训练系列产品/Atlas A3 推理系列产品 Atlas 推理系列产品AI Core Atlas 200I/500 A2 推理产品 Ascend 950PR/Ascend 950DT Kirin X90 Kirin 9030</td></tr><tr><td>half</td><td>half</td><td>float</td><td>64</td><td>Atlas 训练系列产品 Atlas A2 训练系列产品/Atlas A2 推理系列产品 Atlas A3 训练系列产品/Atlas A3 推理系列产品 Atlas 推理系列产品AI Core Atlas 200I/500 A2 推理产品 Ascend 950PR/Ascend 950DT Kirin X90 Kirin 9030</td></tr><tr><td>int64_t</td><td>int64_t</td><td>int64_t</td><td>64</td><td>Ascend 950PR/Ascend 950DT</td></tr><tr><td>uint64_t</td><td>uint64_t</td><td>uint64_t</td><td>64</td><td>Ascend 950PR/Ascend 950DT</td></tr><tr><td>bfloat16_t</td><td>bfloat16_t</td><td>bfloat16_t</td><td>128</td><td>Ascend 950PR/Ascend 950DT</td></tr></tbody></table><h2 id="返回值说明" tabindex="-1">返回值说明 <a class="header-anchor" href="#返回值说明" aria-label="Permalink to &quot;返回值说明&quot;">​</a></h2><p>无</p><h2 id="约束说明" tabindex="-1">约束说明 <a class="header-anchor" href="#约束说明" aria-label="Permalink to &quot;约束说明&quot;">​</a></h2><ul><li><p>操作数地址对齐要求请参见<a href="./../../../通用说明和约束.html#section796754519912">通用地址对齐约束</a>。</p></li><li><p>操作数地址重叠约束请参考<a href="./../../../通用说明和约束.html#section668772811100">通用地址重叠约束</a>。</p></li><li><p>使用tensor高维切分计算接口时，src和scalar的数据类型为half、dst的数据类型为float的情况下，一个迭代处理的源操作数元素个数需要和目的操作数保持一致，所以每次迭代选取前4个datablock参与计算。设置Repeat Stride参数和mask参数以及地址重叠时，需要考虑该限制。</p></li><li><p>针对Ascend 950PR/Ascend 950DT，uint64_t/int64_t数据类型仅支持tensor前n个数据计算接口。</p></li></ul><h2 id="调用示例" tabindex="-1">调用示例 <a class="header-anchor" href="#调用示例" aria-label="Permalink to &quot;调用示例&quot;">​</a></h2><p>本样例中只展示Compute流程中的部分代码。如果您需要运行样例代码，请参考完整样例<a href="https://gitcode.com/cann/asc-devkit/tree/master/examples/01_simd_cpp_api/02_features/03_basic_api/02_memory_vector_compute/element_wise_compound_compute" target="_blank" rel="noreferrer">复合计算样例</a>。</p><ul><li><p>tensor高维切分计算样例-mask连续模式</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>// repeatTime = 4, mask = 128, 128 elements one repeat, 512 elements total</span></span>
<span class="line"><span>// srcLocal数据类型为half，scalar数据类型为half，dstLocal数据类型为half</span></span>
<span class="line"><span>// dstBlkStride, srcBlkStride = 1, no gap between blocks in one repeat</span></span>
<span class="line"><span>// dstRepStride, srcRepStride = 8, no gap between repeats </span></span>
<span class="line"><span>AscendC::Axpy(dstLocal, srcLocal, (half)2.0, 128, 4,{ 1, 1, 8, 8 });</span></span>
<span class="line"><span></span></span>
<span class="line"><span>// srcLocal数据类型为half，scalar数据类型为half，dstLocal数据类型为float</span></span>
<span class="line"><span>// repeatTime = 8, mask = 64, 64 elements one repeat, 512 elements total</span></span>
<span class="line"><span>// dstBlkStride, srcBlkStride = 1, no gap between blocks in one repeat</span></span>
<span class="line"><span>// dstRepStride = 8, srcRepStride = 4, no gap between repeats </span></span>
<span class="line"><span>AscendC::Axpy(dstLocal, srcLocal, (half)2.0, 64, 8,{ 1, 1, 8, 4 }); // 每次迭代选取源操作数前4个datablock参与计算</span></span></code></pre></div></li><li><p>tensor高维切分计算样例-mask逐bit模式</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>uint64_t mask[2] = { 0xFFFFFFFFFFFFFFFF, 0xFFFFFFFFFFFFFFFF };</span></span>
<span class="line"><span>// repeatTime = 4, 128 elements one repeat, 512 elements total, half精度组合</span></span>
<span class="line"><span>// dstBlkStride, srcBlkStride = 1, no gap between blocks in one repeat</span></span>
<span class="line"><span>// dstRepStride, srcRepStride = 8, no gap between repeats</span></span>
<span class="line"><span>AscendC::Axpy(dstLocal, srcLocal, (half)2.0, mask, 4,{ 1, 1, 8, 8 });</span></span></code></pre></div></li><li><p>tensor前n个数据计算样例</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>AscendC::Axpy(dstLocal, src0Local, (half)2.0, 512);// half精度组合</span></span></code></pre></div></li></ul><p>结果示例如下：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>输入数据(src0Local):</span></span>
<span class="line"><span>[1. 2. 3. 4. 5. 6. ... 512.]</span></span>
<span class="line"><span>输入数据(scalarValue):2.0</span></span>
<span class="line"><span>输出数据(dstLocal)初始值:</span></span>
<span class="line"><span>[0. 0. 0. 0. 0. 0. ... 0.]</span></span>
<span class="line"><span>进行Axpy计算后，输出数据(dstLocal):</span></span>
<span class="line"><span>[2. 4. 6. 8. 10. 12. ... 1024.]</span></span></code></pre></div>`,24)])])}const g=a(d,[["render",p]]);export{m as __pageData,g as default};
